	@Test
	void repeatQuoteWorkDoesNotGrowWithUnrelatedArenaEntries() {
		try (Harness h = harness(pattern("x"), Long.MAX_VALUE, Long.MAX_VALUE, 100_000_000L);
				PackedPhysicalRegion region = ready(h.factory.open())) {
			var proof = ready(region.cover(region.root(), new PackedPhysicalRegion.Occurrence[] { region.root() }));
			PackedCostEstimate target = cost(3.0d, 0.0d);
			ready(proof.quote(target));
			long before = h.budget.providerWorkUnits();
			ready(proof.quote(target));
			long firstHit = h.budget.providerWorkUnits() - before;
			for (int value = 10; value < 70; value++) {
				ready(proof.quote(cost(value, 0.0d)));
			}
			before = h.budget.providerWorkUnits();
			ready(proof.quote(target));
			long grownHit = h.budget.providerWorkUnits() - before;
			assertEquals(firstHit, grownHit,
					"the first-interned vector stays at its own slot when the unrelated arena grows");
		}
	}

