	@Test
	void partialGrowthAndRehashRefusalsDoNotPublishVectors() {
		for (int initialCount : new int[] { 8, 10 }) {
			long required = workForNextUniqueQuote(initialCount);
			try (Harness h = harness(pattern("x")); PackedPhysicalRegion region = ready(h.factory.open())) {
				var proof = ready(region.cover(region.root(), new PackedPhysicalRegion.Occurrence[] { region.root() }));
				for (int value = 1; value <= initialCount; value++) {
					ready(proof.quote(cost(value, 0.0d)));
				}
				long oldFingerprint = h.memo.costVectors().digest(1);
				long retained = h.budget.retainedBytes();
				assertTrue(h.work.tryReserve(h.work.remainingWorkUnits() - required + 1));
				long before = h.budget.providerWorkUnits();
				assertEquals(PackedPhysicalRegion.Status.WORK_REFUSED,
						proof.quote(cost(initialCount + 1, 0.0d)).status());
				assertTrue(h.budget.providerWorkUnits() > before, "work already performed remains charged");
				assertTrue(h.budget.retainedBytes() > retained,
						"allocated growth scratch remains charged even though publication was refused");
				assertEquals(oldFingerprint, h.memo.costVectors().digest(1));
				assertThrows(IndexOutOfBoundsException.class, () -> h.memo.costVectors()
						.isKnown(initialCount + 1,
								PackedCostDimensionRegistry.SOURCE_ROW_EVENTS));
				assertEquals(initialCount + 1, h.memo.costVectors().importQuantities(cost(1000.0d, 0.0d)),
						"a refused insertion must not publish a vector or a partial table");
				for (int value = 1; value <= initialCount; value++) {
					assertEquals(value, h.memo.costVectors().importQuantities(cost(value, 0.0d)));
				}
			}
		}
	}

