	@Test
	void meteredAlgebraPreservesIntervalsAndSharedArenaAcrossGrowth() {
		try (Harness h = harness(pattern("x")); PackedPhysicalRegion region = ready(h.factory.open())) {
			PackedCostVectorArena arena = h.memo.costVectors();
			int dimension = PackedCostDimensionRegistry.SOURCE_ROW_EVENTS;
			arena.resetBuilderToUnknown();
			arena.setBuilderInterval(dimension, 1.0d, 2.0d, 3.0d, 11);
			int left = arena.internBuilder();
			arena.resetBuilderToUnknown();
			arena.setBuilderInterval(dimension, 4.0d, 5.0d, 6.0d, 22);
			int right = arena.internBuilder();
			int[] children = { right };
			PackedCostAlgebra algebra = h.memo.costAlgebra();
			int expected = algebra.compose(PackedCostAlgebra.CompositionMode.SEQUENTIAL_SUM, left, children, 0, 1, 1L);
			int metered = algebra.compose(PackedCostAlgebra.CompositionMode.SEQUENTIAL_SUM, left, children, 0, 1, 1L,
					h.work, h.memory, 0L);
			assertEquals(expected, metered);
			assertEquals(5.0d, arena.lower(metered, dimension));
			assertEquals(7.0d, arena.point(metered, dimension));
			assertEquals(9.0d, arena.upper(metered, dimension));
			assertEquals(PackedCostVectorArena.MIXED_LINEAGE_ID, arena.lineageId(metered, dimension));
			var proof = ready(region.cover(region.root(), new PackedPhysicalRegion.Occurrence[] { region.root() }));
			for (int value = 20; value < 40; value++) {
				ready(proof.quote(cost(value, 0.0d)));
			}
			assertEquals(1.0d, arena.lower(left, dimension));
			assertEquals(3.0d, arena.upper(left, dimension));
			assertEquals(11, arena.lineageId(left, dimension));
			assertEquals(9.0d, arena.upper(metered, dimension));
		}
	}

