	@Test
	void estimateScopeMustExactlyCoverRegionOrBoundary() {
		try (Harness h = harness(new Join(pattern("a"), new Join(pattern("b"), pattern("c"))));
				PackedPhysicalRegion region = ready(h.factory.open())) {
			var root = region.root();
			var left = ready(region.child(root, 0));
			var inner = ready(region.child(root, 1));
			var partial = ready(region.cover(root, new PackedPhysicalRegion.Occurrence[] { root, left }));
			var single = ready(region.cover(root, new PackedPhysicalRegion.Occurrence[] { root }));
			PackedCostEstimate unknown = new PackedCostEstimate();
			unknown.setRows(1.0d, 1.0d);
			assertAll(
					() -> assertEquals(PackedPhysicalRegion.Status.UNSUPPORTED,
							partial.quote(localCost(1.0d, 0.0d)).status(), "local cannot cover multiple nodes"),
					() -> assertEquals(PackedPhysicalRegion.Status.UNSUPPORTED,
							single.quote(cost(1.0d, 0.0d)).status(), "inclusive already includes boundary children"),
					() -> assertEquals(PackedPhysicalRegion.Status.UNSUPPORTED,
							single.boundaryCost(1, localCost(1.0d, 0.0d)).status(), "local cannot cover a subtree"),
					() -> assertEquals(PackedPhysicalRegion.Status.EVIDENCE_UNAVAILABLE,
							single.quote(unknown).status(), "scalar rows do not declare physical scope"),
					() -> assertEquals(PackedPhysicalRegion.Status.EVIDENCE_UNAVAILABLE,
							single.boundaryCost(0, unknown).status(), "boundary scope is also required"));
			assertSame(inner, single.boundary(1));
		}
	}

	@Test
	void localRootAndCompleteBoundaryCostsAreAddedOnce() {
		try (Harness h = harness(new Join(pattern("a"), new Join(pattern("b"), pattern("c"))));
				PackedPhysicalRegion region = ready(h.factory.open())) {
			var root = region.root();
			var inner = ready(region.child(root, 1));
			var parent = ready(region.cover(root, new PackedPhysicalRegion.Occurrence[] { root }));
			var rootEstimate = localCost(2.0d, 0.0d);
			var rootQuote = ready(parent.quote(rootEstimate));
			rootEstimate.setReplacesChildWork(true);
			var left = ready(parent.boundaryCost(0, localCost(7.0d, 0.0d)));
			var innerInclusive = ready(parent.boundaryCost(1, cost(20.0d, 0.0d)));
			assertEquals(PackedCostEstimate.CostScope.LOCAL, rootQuote.scope());
			assertEquals(PackedCostEstimate.CostScope.LOCAL, left.scope());
			assertEquals(PackedCostEstimate.CostScope.INCLUSIVE, innerInclusive.scope());
			var total = ready(parent.composeInclusive(rootQuote,
					new PackedPhysicalRegion.BoundaryCost[] { left, innerInclusive }));
			assertEquals(29.0d, total.point(PackedCostDimensionRegistry.SOURCE_ROW_EVENTS));
			assertEquals(PackedCostEstimate.CostScope.INCLUSIVE, total.scope());

			var child = ready(region.cover(inner, new PackedPhysicalRegion.Occurrence[] { inner }));
			var nested = ready(child.composeInclusive(ready(child.quote(localCost(5.0d, 0.0d))),
					new PackedPhysicalRegion.BoundaryCost[] { ready(child.boundaryCost(0, localCost(7.0d, 0.0d))),
							ready(child.boundaryCost(1, localCost(8.0d, 0.0d))) }));
			var nestedBoundary = ready(parent.boundaryCost(1, nested));
			assertEquals(PackedCostEstimate.CostScope.INCLUSIVE, nestedBoundary.scope());
			var nestedTotal = ready(parent.composeInclusive(rootQuote,
					new PackedPhysicalRegion.BoundaryCost[] { left, nestedBoundary }));
			assertEquals(29.0d, nestedTotal.point(PackedCostDimensionRegistry.SOURCE_ROW_EVENTS));
		}
	}

