				assertThrows(IllegalArgumentException.class,
						() -> h.work.bindRegionGeneration(new PackedQueryView(foreignQuery), h.memo, h.memory));
				var currentFactory = h.work.bindRegionGeneration(new PackedQueryView(query), replacement, h.memory);
				assertThrows(IllegalStateException.class, h.factory::open);
				assertThrows(IllegalStateException.class, region::root);
				assertThrows(IllegalStateException.class, quote::coverage);
