	@Test
	void staleProofQuoteAndWorkHandlesFailAfterSessionClose() {
		Harness h = harness(new Join(pattern("a"), pattern("b")));
		var open = h.factory.open();
		var region = ready(open);
		var root = region.root();
		var proof = ready(region.cover(root, new PackedPhysicalRegion.Occurrence[] { root }));
		var quoteResult = proof.quote(localCost(1.0, 0.0));
		var quote = ready(quoteResult);
		var first = ready(proof.boundaryCost(0, cost(1.0, 0.0)));
		var second = ready(proof.boundaryCost(1, cost(1.0, 0.0)));
		var vector = ready(proof.composeInclusive(quote, new PackedPhysicalRegion.BoundaryCost[] { first, second }));
		h.close();
		assertThrows(IllegalStateException.class, h.factory::open);
		assertThrows(IllegalStateException.class, h.work::remainingWorkUnits);
		assertThrows(IllegalStateException.class, () -> h.work.tryReserve(0));
		assertThrows(IllegalStateException.class, () -> h.memory.tryReserve(0));
		assertThrows(IllegalStateException.class, open::status);
		assertThrows(IllegalStateException.class, open::value);
		assertThrows(IllegalStateException.class, region::root);
		assertThrows(IllegalStateException.class, root::relationId);
		assertThrows(IllegalStateException.class, root::childOrdinal);
		assertThrows(IllegalStateException.class, proof::root);
		assertThrows(IllegalStateException.class, proof::coveredCount);
		assertThrows(IllegalStateException.class, proof::boundaryCount);
		assertThrows(IllegalStateException.class, quoteResult::value);
		assertThrows(IllegalStateException.class, quote::coverage);
		assertThrows(IllegalStateException.class, quote::scope);
		assertThrows(IllegalStateException.class, first::occurrence);
		assertThrows(IllegalStateException.class, first::scope);
		assertThrows(IllegalStateException.class, () -> vector.isKnown(PackedCostDimensionRegistry.SOURCE_ROW_EVENTS));
		assertThrows(IllegalStateException.class, vector::scope);
		assertThrows(IllegalStateException.class, () -> vector.point(PackedCostDimensionRegistry.SOURCE_ROW_EVENTS));
		try (Harness reopened = new Harness(h.query,
				new PackedPlannerLimits(1_000_000L, Long.MAX_VALUE, 10_000_000L, 1_000_000L));
				PackedPhysicalRegion next = ready(reopened.factory.open())) {
			var nextProof = ready(next.cover(next.root(), new PackedPhysicalRegion.Occurrence[] { next.root() }));
			assertThrows(IllegalStateException.class,
					() -> nextProof.composeInclusive(quote, new PackedPhysicalRegion.BoundaryCost[0]));
		}
	}

	@Test
	void exactFitOneShortDeadlineAndResourceRefusalsAreDistinct() {
		try (Harness exact = harness(pattern("x"), 1L, Long.MAX_VALUE, 1_000_000L)) {
			long before = exact.budget.providerWorkUnits();
			try (PackedPhysicalRegion region = ready(exact.factory.open())) {
				assertEquals(before + 1L, exact.budget.providerWorkUnits());
				assertEquals(PackedPhysicalRegion.Status.WORK_REFUSED, exact.factory.open().status());
			}
		}
		try (Harness oneShort = harness(new Join(pattern("a"), pattern("b")))) {
			try (PackedPhysicalRegion region = ready(oneShort.factory.open())) {
				var root = region.root();
				ready(region.child(root, 0));
				ready(region.child(root, 1));
				assertTrue(oneShort.work.tryReserve(oneShort.work.remainingWorkUnits() - 1L));
				long bytes = oneShort.budget.retainedBytes();
				assertEquals(PackedPhysicalRegion.Status.WORK_REFUSED,
						region.cover(root, new PackedPhysicalRegion.Occurrence[] { root }).status());
				assertEquals(bytes, oneShort.budget.retainedBytes(), "no allocation before traversal admission");
			}
		}
		try (Harness deadline = harness(pattern("d"), 10L, Long.MIN_VALUE, 1_000_000L)) {
			long bytes = deadline.budget.retainedBytes();
			assertEquals(PackedPhysicalRegion.Status.DEADLINE_EXPIRED, deadline.factory.open().status());
			assertEquals(bytes, deadline.budget.retainedBytes());
		}
		try (Harness firstWork = harness(pattern("d"), 0L, Long.MIN_VALUE, 1_000_000L)) {
			assertEquals(PackedPhysicalRegion.Status.WORK_REFUSED, firstWork.factory.open().status(),
					"the budget refused work before it sampled the expired deadline");
		}
		try (Harness memory = harness(pattern("m"))) {
			assertTrue(
					memory.budget.tryReserveBytes(memory.budget.retainedByteLimit() - memory.budget.retainedBytes()));
			long bytes = memory.budget.retainedBytes();
			assertEquals(PackedPhysicalRegion.Status.RESOURCE_REFUSED, memory.factory.open().status());
			assertEquals(bytes, memory.budget.retainedBytes());
		}
	}

	/**
	 * The mandatory-completion scope never refuses provider work for the deadline, so a refusal inside it is a
	 * provider-work refusal even after the optional-search deadline has latched.
	 */
	@Test
	void mandatoryScopeRefusalAfterTheDeadlineIsAWorkRefusal() {
		try (Harness mandatory = harness(pattern("d"), 0L, Long.MIN_VALUE, 1_000_000L)) {
			assertFalse(mandatory.budget.sampleDeadline());
			assertTrue(mandatory.budget.deadlineReached(), "the optional-search deadline must have latched");
			boolean previous = mandatory.work.enterMandatoryCompletion();
			try {
				assertEquals(PackedPhysicalRegion.Status.WORK_REFUSED, mandatory.factory.open().status(),
						"the mandatory scope refused provider work at the provider-work limit, not at the deadline");
			} finally {
				mandatory.work.leaveMandatoryCompletion(previous);
			}
			assertEquals(PackedPhysicalRegion.Status.DEADLINE_EXPIRED, mandatory.factory.open().status(),
					"outside the mandatory scope the latched deadline explains the refusal");
		}
	}

